--
-- Name: properties_set_password(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.properties_set_password(p_password text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  IF NOT public.is_properties_user() THEN
    RAISE EXCEPTION 'غير مصرح';
  END IF;
  IF p_password IS NULL OR length(p_password) < 4 THEN
    RAISE EXCEPTION 'الباسورد قصير جداً';
  END IF;
  INSERT INTO public.property_module_settings (id, password_hash, updated_at)
  VALUES (true, extensions.crypt(p_password, extensions.gen_salt('bf')), now())
  ON CONFLICT (id) DO UPDATE SET password_hash = EXCLUDED.password_hash, updated_at = now();
  RETURN true;
END;
$$;


ALTER FUNCTION public.properties_set_password(p_password text) OWNER TO postgres;

--
-- Name: properties_verify_password(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.properties_verify_password(p_password text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_hash text;
BEGIN
  IF NOT public.is_properties_user() THEN
    RETURN false;
  END IF;
  SELECT password_hash INTO v_hash FROM public.property_module_settings WHERE id = true;
  IF v_hash IS NULL THEN
    RETURN false; -- ما تحدد باسورد بعد
  END IF;
  RETURN extensions.crypt(p_password, v_hash) = v_hash;
END;
$$;


ALTER FUNCTION public.properties_verify_password(p_password text) OWNER TO postgres;

